L=['1111','1000','1011','0010']; R=['1010','1100','0110','1100']; O=['0000','0011','0100','1001']

def rot(a): return [''.join(a[3-j][i] for j in range(4)) for i in range(4)]
def flip(a): return [s[::-1] for s in a]
trans={}
a=R
for k in range(4):
    trans[f'rot{k*90}']=a
    trans[f'rot{k*90}_flip']=flip(a)
    a=rot(a)
for name,b in trans.items():
    ops={
      'and':[''.join(str(int(x)&int(y)) for x,y in zip(p,q)) for p,q in zip(L,b)],
      'or':[''.join(str(int(x)|int(y)) for x,y in zip(p,q)) for p,q in zip(L,b)],
      'xor':[''.join(str(int(x)^int(y)) for x,y in zip(p,q)) for p,q in zip(L,b)],
      'LminusR':[''.join(str(int(x) and not int(y) and 1 or 0) for x,y in zip(p,q)) for p,q in zip(L,b)],
      'RminusL':[''.join(str(int(y) and not int(x) and 1 or 0) for x,y in zip(p,q)) for p,q in zip(L,b)],
    }
    for op,x in ops.items():
      if x==O: print('EXACT',name,op)
      score=sum(c==d for row1,row2 in zip(x,O) for c,d in zip(row1,row2))
